-- 0006_rights_situation_map_rebuild.sql
--
-- Why: the shipped situation -> rights map was not topical. A student was told to
-- check "arnona discount for senior citizens" as a must-check, and a reservist was
-- shown "tax credit points for a divorced parent". Citizens were getting answers
-- that are not true for them, which is worse than getting none.
--
-- What: every non-fund catalog row carries a sourced udience paragraph stating
-- who is actually entitled. Each of the 453 rows was re-classified against that
-- paragraph (not against its title), producing 1,405 situation assignments split
-- into core (main) and conditional (more). Fund rows are unaffected - they are
-- served through health_pool, not through the situation map.
--
-- The previous map is preserved in rights.situation_map_backup_20260728.
-- Applied to uhnrgujbdxhhmoxcjria on 2026-07-28; this file is the reproducible record.
-- The live site reads this table at runtime, so no redeploy is involved.
create table if not exists rights.situation_map_backup_20260728 as select * from rights.situation_map;
update rights.situation_map m set codes = n.codes
